private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // both null => true
    if (str == null && suffix == null) {
        return true;
    }
    // one is null => false
    if (str == null || suffix == null) {
        return false;
    }
    // empty suffix always matches
    if (suffix.isEmpty()) {
        return true;
    }
    // if suffix longer than str => false
    if (suffix.length() > str.length()) {
        return false;
    }
    int start = str.length() - suffix.length();
    String strLast = str.substring(start);
    return ignoreCase ? strLast.equalsIgnoreCase(suffix) : strLast.equals(suffix);
}

