private void enlarge(final int size){
    int currentCapacity = bytes.length;
    int requiredCapacity = currentCapacity + size;
    if (requiredCapacity > currentCapacity){
        int newCapacity = Math.max(currentCapacity << 1, requiredCapacity);
        if (newCapacity == 0) newCapacity = size; // handle empty initial array
        byte[] newBytes = new byte[newCapacity];
        System.arraycopy(bytes, 0, newBytes, 0, currentCapacity);
        bytes = newBytes;
    }
}

