public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength){
    if(byteLength < 0){
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    // Ensure capacity for the new data
    this.ensureCapacity(this.size + byteLength);
    if (byteArrayValue == null) {
        // fill with null bytes (0)
        for (int i = 0; i < byteLength; i++) {
            this.buffer[this.size + i] = 0;
        }
    } else {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
            throw new ArrayIndexOutOfBoundsException("byteOffset out of bounds");
        }
        if (byteLength > byteArrayValue.length - byteOffset) {
            throw new ArrayIndexOutOfBoundsException("byteLength exceeds source array bounds");
        }
        System.arraycopy(byteArrayValue, byteOffset, this.buffer, this.size, byteLength);
    }
    this.size += byteLength;
    return this;
}

