private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) return;
    int i = 0;
    int len = descriptor.length();
    if (descriptor.charAt(i) == '(') {
        // Method descriptor: pop argument types only
        i++; // skip '('
        while (i < len && descriptor.charAt(i) != ')') {
            int tlen = typeLength(descriptor, i);
            outputFrameStack.pop(); // remove one type from the stack
            i += tlen;
        }
        // return type is ignored (including void)
    } else {
        // Single type descriptor
        int tlen = typeLength(descriptor, i);
        outputFrameStack.pop();
    }
}

