private void putAbstractTypes(final int start, final int end){
    for (int i = start; i < end; ++i) {
        AbstractType type = currentFrame.get(i);
        stackMapTableEntries.putByte(type.tag);
        switch (type.tag) {
        case 7: // Object
            stackMapTableEntries.putShort(type.constantPoolIndex);
            break;
        case 8: // Uninitialized
            stackMapTableEntries.putShort(type.offset);
            break;
        default:
            // Primitive types, top, null, uninitialized_this have no extra data
            break;
        }
    }
