final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Skip magic (4 bytes) + minor version (2 bytes) + major version (2 bytes)
    int pos = 8;
    // Read constant pool count (2 bytes)
    pos += 2; // read count but ignore it for traversal
    int entry = 1;
    while (entry < constantPoolEntryIndex) {
        byte tag = classFileBuffer[pos++];
        switch (tag) {
            case 1: { // CONSTANT_Utf8
                int len = ((classFileBuffer[pos++] & 0xFF) << 8) | (classFileBuffer[pos++] & 0xFF);
                pos += len;
                break;
            }
            case 3: case 4: { // Integer, Float
                pos += 4;
                break;
            }
            case 5: case 6: { // Long, Double
                pos += 8;
                entry++; // takes two indices
                break;
            }
            case 7: case 8: { // Class, String
                pos += 2;
                break;
            }
            case 9: case 10: case 11: case 12: case 18: { // Fieldref, Methodref, InterfaceMethodref, NameAndType, InvokeDynamic
                pos += 4;
                break;
            }
            case 15: { // MethodHandle
                pos += 3;
                break;
            }
            case 16: { // MethodType
                pos += 2;
                break;
            }
            default:
                throw new IllegalArgumentException("Invalid constant pool tag:" + tag);
        }
        entry++;
    }
    // Now pos points to the tag of the target entry
    byte tag = classFileBuffer[pos++];
    if (tag != 1) {
        throw new IllegalArgumentException("Expected CONSTANT_Utf8 (tag 1) but got tag " + tag);
    }
    int utfLen = ((classFileBuffer[pos++] & 0xFF) << 8) | (classFileBuffer[pos++] & 0xFF);
    String tmp = new String(classFileBuffer, pos, utfLen, java.nio.charset.StandardCharsets.UTF_8);
    int len = tmp.length();
    if (len > charBuffer.length) {
        throw new IllegalArgumentException("charBuffer too small: required " + len);
    }
    tmp.getChars(0, len, charBuffer, 0);
    return new String(charBuffer, 0, len);
}

