public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    try {
        if (file.isDirectory()) {
            File[] children = file.listFiles();
            if (children != null) {
                for (File child : children) {
                    forceDeleteOnExit(child); // register child first
                }
            }
        }
        file.deleteOnExit(); // registers this file or directory for deletion on JVM exit
    } catch (SecurityException e) {
        throw new IOException("Failed to register deletion on exit for " + file.getAbsolutePath(), e);
    }
}

