static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    int nullCount = 0;
    for (Object o : array) {
        if (o == null) {
            nullCount++;
        }
    }
    if (nullCount == 0) {
        // safe to cast if the original array is a String[]
        return (String[]) array;
    }
    int nonNullCount = array.length - nullCount;
    String[] result = new String[nonNullCount];
    int idx = 0;
    for (Object o : array) {
        if (o != null) {
            result[idx++] = (String) o;
        }
    }
    return result;
}

