@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    if (!Character.class.equals(type) && !char.class.equals(type)) {
        throw new IllegalArgumentException("Target type must be java.lang.Character or char");
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new Exception("String cannot be converted to Character: length " + str.length());
        }
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal >= Character.MIN_VALUE && intVal <= Character.MAX_VALUE) {
            return (char) intVal;
        } else {
            throw new Exception("Numeric value out of char range: " + intVal);
        }
    }
    if (value instanceof Boolean) {
        return ((Boolean) value) ? '1' : '0';
    }
    String str = value.toString();
    if (str.length() == 1) {
        return str.charAt(0);
    }
    throw new Exception("Cannot convert value to Character: " + value);
}

