public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Retrieve all vertices from the result map
    List<V> vertices = new ArrayList<>(resultMap.values());
    // Add all vertices to the target graph
    for (V v : vertices) {
        target.addVertex(v);
    }
    // Split the vertices into two partitions
    int mid = vertices.size() / 2;
    List<V> firstPartition = vertices.subList(0, mid);
    List<V> secondPartition = vertices.subList(mid, vertices.size());
    // Add edges between every pair of vertices from the two partitions
    for (V u : firstPartition) {
        for (V w : secondPartition) {
            target.addEdge(u, w);
        }
    }
}

