private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start);
    // If the start node is the stop node, return immediately.
    if (start == stop) {
        return circ;
    }
    // Check the predicate on the start node.
    if (predicate.test(start)) {
        return circ;
    }
    // Traverse the outer face in the specified direction until
    // we hit the stop node or find a node that satisfies the predicate.
    while (true) {
        circ = dir > 0 ? circ.next() : circ.previous();
        Node cur = circ.node();
        if (cur == stop) {
            return circ;
        }
        if (predicate.test(cur)) {
            return circ;
        }
        // Prevent an infinite loop in case the traversal cycles back to the start.
        if (cur == start) {
            break;
        }
    }
    // As a fallback return a circulator positioned at the stop node.
    return new OuterFaceCirculator(stop);
}

