protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if(tour == null || tour.isEmpty()){
        throw new IllegalArgumentException("Tour set cannot be null or empty");
    }
    List<E> orderedEdges = new ArrayList<>(tour.size());
    Set<E> remainingEdges = new HashSet<>(tour);

    // start with an arbitrary edge
    E currentEdge = remainingEdges.iterator().next();
    V startVertex = graph.getEdgeSource(currentEdge);
    V currentVertex = graph.getEdgeTarget(currentEdge);
    orderedEdges.add(currentEdge);
    remainingEdges.remove(currentEdge);

    // chain the remaining edges to form a path
    while (!remainingEdges.isEmpty()) {
        E nextEdge = null;
        for (E e : remainingEdges) {
            if (graph.getEdgeSource(e).equals(currentVertex) ||
                graph.getEdgeTarget(e).equals(currentVertex)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            throw new IllegalArgumentException("Edges do not form a continuous path");
        }
        orderedEdges.add(nextEdge);
        remainingEdges.remove(nextEdge);
        // determine the next vertex (opposite to currentVertex)
        currentVertex = graph.getEdgeSource(nextEdge).equals(currentVertex)
                       ? graph.getEdgeTarget(nextEdge)
                       : graph.getEdgeSource(nextEdge);
    }

    // compute total weight of the path
    double weight = 0.0;
    for (E e : orderedEdges) {
        weight += graph.getEdgeWeight(e);
    }

    V endVertex = currentVertex;
    return new SimpleGraphPath<>(graph, startVertex, endVertex, orderedEdges, weight);
}

