private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel){
    if (minLabel == 0) return; // nothing to do
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) return; // invalid index
    Set<Integer> src = bucketsByLabel.get(minLabel);
    if (src == null || src.isEmpty()) return;
    Set<Integer> dest = bucketsByLabel.get(0);
    if (dest == null) {
        dest = new HashSet<>();
        bucketsByLabel.set(0, dest);
    }
    // collect vertices to avoid modification during iteration
    List<Integer> vertices = new ArrayList<>(src);
    for (int v : vertices) {
        dest.add(v);
        labels.set(v, 0);
    }
    src.clear();
}

