private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    int n = bounds.size();
    int[] suffix = new int[n];
    long runningSum = 0;
    for (int i = n - 1; i >= 0; i--) {
        int val = bounds.get(i);
        runningSum += val;
        suffix[i] = (int) runningSum;
    }
    long totalSum = runningSum;
    java.util.ArrayList<Integer> suffixList = new java.util.ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        suffixList.add(suffix[i]);
    }
    return new Pair<>(suffixList, totalSum);
}

