private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // A subgraph with 0 or 1 vertices is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }

    // Convert set to list for indexed access
    List<V> vertexList = new ArrayList<>(vertices);
    int n = vertexList.size();

    for (int i = 0; i < n; i++) {
        V vi = vertexList.get(i);
        for (int j = i + 1; j < n; j++) {
            V vj = vertexList.get(j);
            // For undirected graphs, containsEdge checks both directions if implemented that way.
            if (!graph.containsEdge(vi, vj) && !graph.containsEdge(vj, vi)) {
                return false; // Missing edge means not a clique
            }
        }
    }
    return true;
}

