    // and append the resulting character(s) to the StringBuilder.
    // The method returns the index of the next unchecked byte.
    int limit = bb.limit();
    if (i >= limit) {
        return i;
    }

    int b1 = bb.get(i) & 0xFF; // unsigned first byte
    int nextIndex = i + 1;

    // 1-byte sequence (ASCII)
    if ((b1 & 0x80) == 0) {
        sb.append((char) b1);
        return nextIndex;
    }

    // 2-byte sequence
    if ((b1 & 0xE0) == 0xC0) {
        if (nextIndex >= limit) return i; // incomplete
        int b2 = bb.get(nextIndex) & 0x3F;
        int cp = ((b1 & 0x1F) << 6) | b2;
        sb.append((char) cp);
        return nextIndex + 1;
    }

    // 3-byte sequence
    if ((b1 & 0xF0) == 0xE0) {
        if (nextIndex + 1 >= limit) return i; // incomplete
        int b2 = bb.get(nextIndex) & 0x3F;
        int b3 = bb.get(nextIndex + 1) & 0x3F;
        int cp = ((b1 & 0x0F) << 12) | (b2 << 6) | b3;
        sb.append((char) cp);
        return nextIndex + 2;
    }

    // 4-byte sequence (surrogate pair)
    if ((b1 & 0xF8) == 0xF0) {
        if (nextIndex + 2 >= limit) return i; // incomplete
        int b2 = bb.get(nextIndex) & 0x3F;
        int b3 = bb.get(nextIndex + 1) & 0x3F;
        int b4 = bb.get(nextIndex + 2) & 0x3F;
        int cp = ((b1 & 0x07) << 18) | (b2 << 12) | (b3 << 6) | b4;
