public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // Remove leading '/' for absolute paths
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    // Split on '/' treating empty segments as they appear (e.g., for path ending with '/')
    String[] rawSegments = path.split("/", -1);
    for (String raw : rawSegments) {
        if (raw.isEmpty()) {
            continue;
        }
        String decoded = raw;
        if (decode) {
            try {
                decoded = java.net.URLDecoder.decode(raw, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 should always be supported; fallback to raw if not
                decoded = raw;
            }
        }
        segments.add(new PathSegmentImpl(raw, decoded));
    }
    return segments;
}

