public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= length) {
                sb.append('\\');
                continue;
            }
            char next = str.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case 'u':
                    if (i + 5 >= length) {
                        throw new Exception("Invalid Unicode escape sequence at position " + i);
                    }
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int codePoint = Integer.parseInt(hex, 16);
                        sb.append((char) codePoint);
