                        throw new Exception("Invalid Unicode escape sequence '\\u" + hex + "' at position " + i);
                    }
                    i += 5;
                    break;
                default:
                    if (next >= '0' && next <= '7') { // octal escape
                        int val = next - '0';
                        int count = 1;
                        int j = i + 2;
                        while (count < 3 && j < length) {
                            char ch = str.charAt(j);
                            if (ch >= '0' && ch <= '7') {
                                val = val * 8 + (ch - '0');
                                count++;
                                j++;
                            } else {
