public static String applyRelativePath(String path,String relativePath){
    // Handle null cases
    if (path == null) {
        return relativePath;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    // Split the base path into components
    String[] baseParts = path.split("/");
    int baseLen = baseParts.length;
    boolean baseEndsWithSlash = path.endsWith("/");
    // Determine if the base path refers to a directory or a file
    int baseIndex = baseEndsWithSlash ? baseLen : baseLen - 1;
    boolean leadingSlash = path.startsWith("/");

    // Prepare a stack for the resulting path components
    String[] stack = new String[baseLen + relativePath.split("/").length];
    int stackLen = 0;

    // Add base components to the stack (skip the file component if base is a file)
    for (int i = 0; i < baseIndex; i++) {
        if (!baseParts[i].isEmpty()) {
            stack[stackLen++] = baseParts[i];
        }
    }

    // Process relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (stackLen > 0) {
                stackLen--;
            }
        } else {
            stack[stackLen++] = part;
        }
    }

    // Build the resulting path string
    StringBuilder result = new StringBuilder();
    if (leadingSlash) {
        result.append("/");
    }
    for (int i = 0; i < stackLen; i++) {
        result.append(stack[i]);
        if (i < stackLen - 1) {
            result.append("/");
        }
    }

    // Handle the case where result is empty but original path started with a slash
    if (result.length() == 0 && leadingSlash) {
        result.append("/");
    }

    return result.toString();
}

