    String pat = (pattern != null ? pattern : "%d [%t] %p %c - %m%n");
    int i = 0;
    while (i < pat.length()) {
        char ch = pat.charAt(i);
        if (ch == '%') {
            i++;
            if (i >= pat.length()) {
                sb.append('%');
                break;
            }
            char token = pat.charAt(i);
            switch (token) {
                case 'd':
                    java.text.SimpleDateFormat df = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
                    sb.append(df.format(new java.util.Date(event.getTimeStamp())));
