                case 'm':
                    sb.append(event.getFormattedMessage());
                    break;
                case 'n':
                    sb.append(System.lineSeparator());
                    break;
                case 't':
                    sb.append(event.getThreadName());
                    break;
                default:
                    sb.append('%').append(token);
            }
        } else {
            sb.append(ch);
        }
        i++;
    }
    return sb.toString();
}

