public String format(final LoggingEvent event){
    // Prepare basic parts of the log message
    long timeMillis = event.getTimeStamp();
    java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
    String time = sdf.format(new java.util.Date(timeMillis));
    String level = event.getLevel().toString();
    String loggerName = event.getLoggerName();
    String threadName = event.getThreadName();
    String message = event.getRenderedMessage();

    StringBuilder sb = new StringBuilder();
    sb.append(time)
      .append(' ')
      .append('[').append(level).append(']')
      .append('[').append(threadName).append(']')
      .append(' ').append(loggerName)
      .append(" - ").append(message);

    // Append stack trace if present
    try {
        Throwable throwable = null;
        // Try Log4j 1.x API
        Object throwableInfo = event.getThrowableInformation();
        if (throwableInfo != null) {
            java.lang.reflect.Method getThrowable = throwableInfo.getClass().getMethod("getThrowable");
            throwable = (Throwable) getThrowable.invoke(throwableInfo);
        }
        // If not found, try Log4j 2.x API
        if (throwable == null && event.getThrowableProxy() != null) {
            try {
                throwable = event.getThrowableProxy().getThrowable();
            } catch (NoSuchMethodError | NoSuchFieldError e) {
                // ignore
            }
        }
        if (throwable != null) {
            java.io.StringWriter sw = new java.io.StringWriter();
            java.io.PrintWriter pw = new java.io.PrintWriter(sw);
            throwable.printStackTrace(pw);
            pw.flush();
            String stack = sw.toString().trim();
            if (!stack.isEmpty()) {
                sb.append("\n");
                sb.append(stack);
            }
        }
    } catch (Exception e) {
        // In case of any reflection or I/O issue, skip stack trace
    }

    return sb.toString();
}

