public static String findAndSubst(String key, Properties props) {
    // Retrieve the value for the given key
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }

    // Compile the regex pattern once
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");

    // Perform substitution iteratively to handle nested expressions
    int maxIterations = 10; // safeguard against infinite loops
    String previous = null;
    int iterations = 0;

    while (iterations < maxIterations && !value.equals(previous)) {
        previous = value;
        java.util.regex.Matcher matcher = pattern.matcher(value);
        java.lang.StringBuilder sb = new java.lang.StringBuilder();

        while (matcher.find()) {
            String varName = matcher.group(1).trim();

            // Resolve the variable: look in props, then in environment variables
            String replacement = props.getProperty(varName);
            if (replacement == null) {
                replacement = System.getenv(varName);
            }
            if (replacement == null) {
                replacement = "";
            }

            // Replace the placeholder with the resolved value
            matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(replacement));
        }
        matcher.appendTail(sb);
        value = sb.toString();
        iterations++;
    }

    return value;
}

