public void abbreviate(final int nameStart, final StringBuffer buf) {
        if (name == null || name.length() <= nameStart) {
            return;  // nothing to abbreviate
        }
        int idx = nameStart;
        boolean firstWord = true;
        while (idx < name.length()) {
            // Skip any leading whitespace before the next word
            while (idx < name.length() && Character.isWhitespace(name.charAt(idx))) {
                idx++;
            }
            if (idx >= name.length()) {
                break;
            }
            // Find the end of the current word
            int wordEnd = idx;
            while (wordEnd < name.length() && !Character.isWhitespace(name.charAt(wordEnd))) {
                wordEnd++;
            }
            String word = name.substring(idx, wordEnd);
            if (firstWord) {
                buf.append(word);          // keep the first word in full
            } else {
                if (!word.isEmpty()) {
                    buf.append(word.charAt(0)).append('.');  // abbreviate subsequent words
                }
            }
            firstWord = false;
            idx = wordEnd;  // move to the next position after the word
        }
    }

