private JsonObject convertProperties(List<KeyStringValuePair> properties) {
    JsonObject jsonObject = new JsonObject();
    if (properties == null) {
        return jsonObject;
    }
    for (KeyStringValuePair pair : properties) {
        if (pair == null) {
            continue;
        }
        String key = pair.getKey();
        if (key == null) {
            continue;
        }
        String value = pair.getValue();
        try {
            // If the value is a valid JSON representation, parse it; otherwise, add as string
            if (value != null && (value.startsWith("{") || value.startsWith("[") || value.matches("^[\\d\\.]+$") || value.equalsIgnoreCase("true") || value.equalsIgnoreCase("false") || value.equalsIgnoreCase("null"))) {
                JsonElement elem = JsonParser.parseString(value);
                jsonObject.add(key, elem);
            } else {
                jsonObject.addProperty(key, value);
            }
        } catch (Exception e) {
            // Fallback to string if parsing fails
            jsonObject.addProperty(key, value);
        }
    }
    return jsonObject;
}

