        if (descriptor.charAt(0) == '(') {
            // Skip '('
            idx = 1;
            // Iterate over the argument types until ')'
            while (idx < descriptor.length() && descriptor.charAt(idx) != ')') {
                // Consume one type descriptor and pop the corresponding stack entry
                int typeEnd = idx + 1; // default for primitive types
                char c = descriptor.charAt(idx);
                if (c == '[') {
                    // Array type: consume all '['
                    while (descriptor.charAt(typeEnd) == '[') {
                        typeEnd++;
                    }
                    // After '[' array dims, there is primitive or object
                    char elem = descriptor.charAt(typeEnd);
                    if (elem == 'L') {
