                }
                // Pop one element from the output stack for this argument
                outputStack.pop();
                // Move idx to the start of the next argument type
                idx = typeEnd;
            }
            // After finishing arguments, break out of the loop
            break;
        } else {
            // Descriptor represents a single type (not a method)
            int typeEnd = idx + 1; // default for primitives
            char c = descriptor.charAt(idx);
            if (c == '[') {
                while (descriptor.charAt(typeEnd) == '[') {
                    typeEnd++;
