public static int nextPrime(int desiredCapacity) {
    int capacity = desiredCapacity;
    if (capacity <= 2) {
        return 2;
    }
    if ((capacity & 1) == 0) {
        capacity++; // make it odd so we can skip evens
    }
    while (true) {
        int sqrt = (int) Math.sqrt(capacity);
        boolean isPrime = true;
        for (int i = 3; i <= sqrt; i += 2) {
            if (capacity % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return capacity;
        }
        capacity += 2; // move to the next odd number
    }
}

