@Override
public String readString() throws IOException {
    // Read the length of the string. We assume an int length prefix.
    int length = in.readInt();
    if (length < 0) {
        throw new IOException("Negative string length: " + length);
    }

    // Read the string bytes.
    byte[] bytes = new byte[length];
    in.readFully(bytes);

    // Convert the bytes to a String using UTF-8 encoding.
    try {
        return new String(bytes, "UTF-8");
    } catch (UnsupportedEncodingException e) {
        // UTF-8 is a guaranteed encoding, but wrap just in case.
        throw new IOException("UTF-8 encoding not available", e);
    }
}

