public final byte[] toByteArray(){
    try {
        java.lang.reflect.Field[] fields = this.getClass().getDeclaredFields();
        java.util.List<java.io.ByteArrayOutputStream> streams = new java.util.ArrayList<>();
        for (java.lang.reflect.Field f : fields) {
            if (f.getType() == java.io.ByteArrayOutputStream.class) {
                f.setAccessible(true);
                Object val = f.get(this);
                if (val != null) {
                    streams.add((java.io.ByteArrayOutputStream) val);
                }
            }
        }
        int totalSize = 0;
        for (java.io.ByteArrayOutputStream s : streams) {
            totalSize += s.size();
        }
        byte[] result = new byte[totalSize];
        int pos = 0;
        for (java.io.ByteArrayOutputStream s : streams) {
            byte[] part = s.toByteArray();
            System.arraycopy(part, 0, result, pos, part.length);
            pos += part.length;
        }
        return result;
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
}

