private void checkIfPackedField() throws IOException {
    // Detect whether the current field has been encoded as a packed repeated
    // field – this is indicated by a type‑2 (length‑delimited) wire format
    // for a repeated field descriptor.
    if (wireType == WIRETYPE_LENGTH_DELIMITED && fieldDescriptor.isRepeated()) {
        // The next varint gives the byte length of the packed block.
        int packedLength = input.readRawVarint32();
        // Record where the packed block ends so that subsequent reads know
        // not to go past it.
        packedEndPosition = input.getPosition() + packedLength;
        // Mark that we are now inside a packed field.
        inPackedField = true;
    } else {
        // Not a packed field – normal scalar handling applies.
        inPackedField = false;
    }
}

